NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Colossians'

CHAPTERS = {
    1: {
        1: 'Pavel, po Božji volji apostol Jezusa Kristusa in naš brat Timótej,',
        2: 'svetim in zvestim bratom v Kristusu, ki ste v Kolósah: ›Milost bodi vam in mir od Boga, našega Očeta in Gospoda Jezusa Kristusa.‹',
        3: 'Zahvaljujemo se Bogu in Očetu našega Gospoda Jezusa Kristusa, ko nenehno molimo za vas,',
        4: 'odkar smo slišali o vaši veri v Kristusa Jezusa in o ljubezni, ki jo imate do vseh svetih;',
        5: 'zaradi upanja, ki je za vas prihranjeno v nebesih, o katerem ste prej slišali v besedi resnice evangelija,',
        6: 'ki je prišel k vam tako, kakor je po vsem svetu; in prinaša sad, kakor tudi v vas, od dneva, ko ste slišali o njem in spoznali Božjo milost v resnici;',
        7: 'kakor ste se tudi naučili od Epafrá, našega dragega soslužabnika, ki je za vas zvest Kristusov služabnik,',
        8: 'ki nam je tudi pojasnil vašo ljubezen v Duhu.',
        9: 'Zaradi tega razloga tudi mi od dneva, ko smo to slišali, ne prenehamo moliti za vas in želimo, da bi bili vi lahko izpolnjeni s spoznanjem njegove volje, v vsej modrosti in duhovnem razumevanju,',
        10: 'da bi lahko hodili vredno Gospoda v vsej všečnosti, bili rodovitni v vsakem dobrem delu in rastli v spoznanju Boga;',
        11: 'okrepljeni z vso močjo, glede na njegovo veličastno moč, v vsej vztrajnosti in potrpežljivosti, z veseljem;',
        12: 'in se zahvaljevali Očetu, ki nas je naredil primerne za udeležence dediščine svetih v svetlobi,',
        13: 'ki nas je osvobodil pred oblastjo teme in nas prenesel v kraljestvo svojega ljubljenega Sina;',
        14: '§ v katerem imamo po njegovi krvi odkupitev, torej odpuščanje grehov;',
        15: 'ki je podoba nevidnega Boga, prvorojenec vsakega ustvarjenega bitja,',
        16: 'kajti po njem so bile ustvarjene vse stvari, ki so na nebu in ki so na zemlji, vidne in nevidne, bodisi so to prestoli ali gospostva ali kneževine ali oblasti; vse stvari so bile ustvarjene po njem in zanj;',
        17: 'in on je pred vsemi stvarmi in po njem vse stvari stojijo skupaj.',
        18: 'In on je glava telesa, cerkve; ki ji je začetek, prvorojenec od mrtvih; da bi lahko v vseh stvareh imel prvenstvo.',
        19: '§ Kajti Očetu je ugajalo, da bi v njem prebivala vsa polnost;',
        20: 'in je sklenil mir po krvi njegovega križa, da po njem pobota k sebi vse stvari; po njem, pravim, bodisi, da so stvari na zemlji ali stvari v nebesih.',
        21: 'In vas, ki ste bili nekoč odtujeni in v svojem mišljenju po zlobnih delih sovražniki, je vendar sedaj pobotal',
        22: 'v telesu njegovega mesa skozi smrt, da vas predstavi svete in neoporečne in brezgrajne v svojem pogledu,',
        23: 'če utemeljeni in ustaljeni nadaljujete v veri in se ne boste oddaljili od upanja evangelija, ki ste ga slišali in ki je bil oznanjen vsakemu ustvarjenemu bitju, ki je pod nebom; katerega sem jaz, Pavel, postal služabnik;',
        24: 'ki se sedaj veselim v svojih trpljenjih za vas in v svojem mesu dopolnjujem to, kar je zaradi njegovega telesa, ki je cerkev, primanjkovalo Kristusovim stiskam;',
        25: 'katerega služabnik sem postal, glede na Božjo razdelitev, ki mi je bila dana za vas, da izpolnim Božjo besedo;',
        26: 'celó skrivnost, ki je bila skrita pred veki in pred rodovi, toda sedaj je razodeta njegovim svetim,',
        27: 'katerim je Bog hotel razodeti kakšna so bogastva slave te skrivnosti med pogani; ki je Kristus v vas, upanje slave,',
        28: '§ katerega oznanjamo in vsakega človeka svarimo in vsakega človeka učimo v vsej modrosti; da lahko vsakega človeka prikažemo popolnega v Kristusu Jezusu;',
        29: 'zato se tudi trudim in se borim, glede na njegovo delovanje, ki v meni mogočno deluje.',
    },
    2: {
        1: 'Kajti hočem, da bi vedeli, kako velik boj imam za vas in za te iz Laodikeje in za mnoge, četudi niso videli mojega obraza v mesu,',
        2: '§ da bodo njihova srca lahko potolažena, stkana skupaj v ljubezni in v vseh bogastvih polnega zagotovila razumevanja, k spoznanju Božje skrivnosti in Očetove in Kristusove;',
        3: 'v katerem so skriti vsi zakladi modrosti in spoznanja.',
        4: 'In to pravim, da vas ne bi katerikoli človek preslepil s prepričevalnimi besedami.',
        5: 'Kajti čeprav sem odsoten v mesu, sem vendar z vami v duhu in se veselim ter zrem vašo urejenost in neomajnost vaše vere v Kristusa.',
        6: 'Tako kakor ste torej sprejeli Gospoda Kristusa Jezusa, tako živite v njem.',
        7: 'Ukoreninjeni in zgrajeni v njem ter potrjeni v veri, kakor ste bili poučeni in v tem obilni z zahvaljevanjem.',
        8: 'Pazite, da vas ne bi katerikoli človek oplenil s filozofijo in prazno prevaro po človeškem izročilu, po temeljnih principih sveta, ne pa po Kristusu.',
        9: 'Kajti v njem telesno prebiva vsa polnost Božanstva.',
        10: 'In vi ste popolni v njem, ki je glava vseh kneževin in oblasti;',
        11: '§ v katerem ste tudi obrezani z obrezo, narejeno brez rok, s slačenjem grešnega mesenega telesa, s Kristusovo obrezo;',
        12: 's krstom pokopani z njim, v katerem ste tudi vi z njim vstali, po veri Božjega delovanja, ki ga je obudil od mrtvih.',
        13: 'In vas, mrtve v vaših grehih in neobrezanosti vašega mesa, je on oživil skupaj z njim ter vam odpustil vse grehe',
        14: 'in izbrisal rokopis odredb, ki so bile zoper nas, ki nam je bil nasproten in ga odstranil s poti ter ga pribil na svoj križ;',
        15: 'in ker imamo pokvarjene kneževine in oblasti, je naredil iz njih javni prikaz, slaveč v tem zmago nad njimi.',
        16: 'Ne pustite torej nobenemu človeku, da vas sodi v jedi ali v pijači ali pri spoštovanju svetega dne ali mlaja ali šabatnih dni;',
        17: 'ki so senca stvari, ki pridejo; toda telo je Kristusovo.',
        18: 'Ne pustite nobenemu človeku, da vas preslepi glede vaše nagrade, [tako da je] prostovoljno ponižen in obožuje angele in se vsiljuje v te stvari, ki jih ni videl, prazno napihnjen s svojim mesenim umom,',
        19: 'ne drži pa se Glave, od katere ima vse telo po sklepih in vezeh nudeno hrano in stkano skupaj raste z rastjo od Boga.',
        20: 'Zatorej, če ste s Kristusom mrtvi temeljnim principom sveta, zakaj ste podrejeni odredbam, kakor da živite v svetu',
        21: '(ne dotikaj, ne okušaj, ne prijemaj,',
        22: 'ki bodo z uporabo vsi odmrli) po človeških zapovedih in naukih?',
        23: 'Katere stvari imajo resnično navidezen prikaz modrosti v pobožnem oboževanju in ponižnosti in zapostavljanju telesa; v zadovoljevanje mesa, ne pa v kakršnokoli vrednost.',
    },
    3: {
        1: 'Če ste bili torej obujeni s Kristusom, iščite te stvari, ki so zgoraj, kjer Kristus sedi na Božji desnici.',
        2: 'Naravnajte svojo naklonjenost na stvari zgoraj, ne na stvari na zemlji.',
        3: 'Kajti umrli ste in vaše življenje je s Kristusom skrito v Bogu.',
        4: 'Ko se bo prikazal Kristus, ki je naše življenje, tedaj se boste tudi vi prikazali z njim v slavi.',
        5: 'Mrtvite torej svoje ude, ki so na zemlji: prešuštvovanje, nečistost, nebrzdano strast, zlo poželjivost in pohlepnost, kar je malikovanje;',
        6: 'kajti zaradi teh stvari prihaja Božji bes na otroke neposlušnosti;',
        7: 'v katerih ste tudi vi nekaj časa hodili, ko ste živeli v njih.',
        8: 'Toda sedaj tudi vse to odložite: jezo, bes, zlobnost, bogokletje, umazan govor iz vaših ust.',
        9: 'Ne lažite drug drugemu, ker ste slekli starega človeka z njegovimi dejanji',
        10: 'in si nadeli novega človeka, ki je obnovljen v spoznanju, po podobi njega, ki ga je ustvaril;',
        11: 'kjer ni niti Grka, niti Juda, obreze, niti neobreze, tujca, Skita, sužnja, niti svobodnega, temveč je Kristus vse in v vseh.',
        12: 'Nadenite si torej, kot Božji izvoljenci, sveti in ljubljeni, čustva usmiljenja, prijaznost, ponižnost mišljenja, krotkost, potrpežljivost;',
        13: 'prizanašajte drug drugemu in odpuščajte drug drugemu, če ima katerikoli človek spor proti komurkoli. Torej kakor je Kristus odpustil vam, tako tudi vi počnite.',
        14: 'In nad vsemi temi stvarmi si oblecite ljubezen, ki je vez popolnosti.',
        15: 'In Božji mir naj vlada v vaših srcih, h kateremu ste tudi poklicani v enem telesu; in bodite hvaležni.',
        16: 'Naj Kristusova beseda bogato prebiva v vas v vsej modrosti; drug drugega učite in opominjajte s psalmi in hvalnicami ter duhovnimi pesmimi in prepevajte Gospodu z milostjo v svojih srcih.',
        17: 'In karkoli delate v besedi ali dejanju, vse delajte v imenu Gospoda Jezusa in po njem dajajte zahvalo Bogu in Očetu.',
        18: 'Žene, podredite se svojim lastnim soprogom, kakor se to spodobi v Gospodu.',
        19: 'Soprogi, ljubíte svoje žene in ne bodite osorni proti njim.',
        20: 'Otroci, ubogajte svoje starše v vseh stvareh, kajti to je zelo prijetno Gospodu.',
        21: 'Očetje, ne provocirajte svojih otrok k jezi, da ne bi izgubili poguma.',
        22: '§ Služabniki, v vseh stvareh ubogajte svoje gospodarje po mesu; ne z navidezno vdanostjo, kakor da bi raje ugajali ljudem; temveč v iskrenosti srca, boječ se Boga.',
        23: 'In karkoli delate, delajte to iz srca, kakor Gospodu in ne ljudem;',
        24: 'vedoč, da boste od Gospoda prejeli nagrado dediščine; kajti vi služite Gospodu Kristusu.',
        25: 'Toda kdor dela krivico, bo za krivico prejel, kar je storil; in ni oziranja na osebe.',
    },
    4: {
        1: 'Gospodarji, dajajte svojim služabnikom to, kar je pravično in primerno; vedoč, da imate tudi vi Gospodarja v nebesih.',
        2: 'Vztrajajte v molitvi in bedite v njej z zahvaljevanjem;',
        3: 'poleg tega molíte tudi za nas, da bi nam Bog odprl vrata izgovarjave, da bomo govorili Kristusovo skrivnost, zaradi katere sem tudi v vezeh;',
        4: 'da jo bom lahko prikazal, kakor sem dolžan govoriti.',
        5: 'Živite v modrosti do teh, ki so zunaj in izkoristite čas.',
        6: 'Naj bo vaš govor vedno z milostjo, začinjen s soljo, da boste lahko vedeli, kako bi morali odgovarjati vsakemu človeku.',
        7: 'Ves moj položaj vam bo razglasil Tihik, ki je ljubljeni brat in zvest služabnik ter soslužabnik v Gospodu;',
        8: '§ ki sem ga k vam poslal z istim namenom, da bi lahko spoznal vaš položaj in potolažil vaša srca;',
        9: 'z Onézimom, zvestim in ljubljenim bratom, ki je eden izmed vas. Dala vam bosta spoznati vse stvari, ki so storjene tukaj.',
        10: 'Pozdravljajo vas Aristarh, moj sojetnik in Marko, sin Barnabove sestre (glede katerega ste prejeli zapovedi; če pride k vam, ga sprejmite)',
        11: 'in Jezus, ki se imenuje Just, ki so iz obreze. Samo ti so moji sodelavci za Božje kraljestvo, ki so mi bili v tolažbo.',
        12: '§ Pozdravlja vas Epafrá, ki je eden izmed vas, Kristusov služabnik, ki se vedno goreče bori za vas v molitvah, da bi lahko stali popolni in dovršeni, v vsej Božji volji.',
        13: 'Kajti prinašam mu pričevanje, da ima veliko gorečnost za vas in za tiste, ki so v Laodikeji in za one v Hierápoli.',
        14: 'Pozdravljata vas Luka, ljubljeni zdravnik in Demá.',
        15: 'Pozdravite brate, ki so v Laodikeji in Nimfása ter cerkev, ki je v njegovi hiši.',
        16: 'In ko preberete to poslanico med vami, poskrbite, da se bo brala tudi v cerkvi Laodikejcev; in da tudi vi preberete poslanico iz Laodikeje.',
        17: 'In Arhipu recite: »Pazi na službo, ki si jo prejel v Gospodu, da jo izpolnjuješ.«',
        18: 'Pozdrav z mojo, Pavlovo roko. Spominjajte se mojih vezi. Milost bodi z vami. Amen. [Napisano iz Rima Kološanom, po Tihiku in Onézimu.]',
    },
}
